head.script:
scwin.onpageload = function() {};
scwin.onpageunload = function() {};
scwin.trigger1_onclick = function(e) {
    requires("uiplugin.popup"); //팝업을 사용하기 위해 반드시 포함되어야 한다.
    //dataList1.getRowJSON와 같은 API 호출 시 반환 객체.
    var rowJSON = {
        "addr": "서울시",
        "name": "손예진",
        "rowStatus": "R"
    };
    //popup에 넘길 data객체.
    var dataObj = {
        type: "json", // 데이터 타입. "xml","string","json","array"
        data: rowJSON, // 전달 데이터 객체.
        name: "rowObj" // 변수명. popup에서 $w.getParameter( "rowObj" )로 깨내올 수 있다.
    };
    var options = {
        id: "popup1",
        type: "window",
        width: "230px",
        height: "250px",
        top: "130px",
        left: "200px",
        popupName: "openPopup1",
        modal: true,
        useIFrame: true,
        frameMode: 'wframe',
        resizable: true,
        status: true,
        menubar: false,
        scrollbars: false,
        title: false,
        useModalStack: true,
        alwaysOnTop: true,
        dataObject: dataObj
    };
    $w.openPopup("wframe_popup_WPFF-9_(WSQ-3058)_sub.xml", options);
};
scwin.__checkErrLog = function() {
    return WebSquare.logger.getErrorLog();
}
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    //Function unitTest
    //Create buy Truong.Luu
    //Create date 06-Mar-2018
    //End unitTest
}
